import{_ as t,c as o,o as a,ae as s}from"./chunks/framework.CFeneB-q.js";const u=JSON.parse('{"title":"PC 端 · 请求封装参考","description":"","frontmatter":{},"headers":[],"relativePath":"pc/references/http-request.md","filePath":"pc/references/http-request.md","lastUpdated":1789438865000}'),d={name:"pc/references/http-request.md"};function c(n,e,r,i,l,p){return a(),o("div",null,[...e[0]||(e[0]=[s(`<h1 id="pc-端-·-请求封装参考" tabindex="-1">PC 端 · 请求封装参考 <a class="header-anchor" href="#pc-端-·-请求封装参考" aria-label="Permalink to &quot;PC 端 · 请求封装参考&quot;">​</a></h1><blockquote><p>行为规格基于 <code>keystone-deliver-ui/src/utils/http/index.js</code>（class HttpClient，2026-09-16 核对）。业务代码只经 <code>@/utils/http</code> 发请求，不要绕过。</p></blockquote><h2 id="基本参数" tabindex="-1">基本参数 <a class="header-anchor" href="#基本参数" aria-label="Permalink to &quot;基本参数&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项</th><th>值</th><th>说明</th></tr></thead><tbody><tr><td>baseURL</td><td><code>VITE_APP_BASE_API</code></td><td>由 <code>pnpm switch:api</code> 写入</td></tr><tr><td>timeout</td><td><strong>120000</strong> ms</td><td>注意与基座 e9-delivery-ui 的 5000 不同</td></tr><tr><td>自动重试</td><td>axios-retry：<code>retries: 2</code>，间隔 <code>retryCount * 2000</code>，<code>shouldResetTimeout</code>，<strong>仅超时（timeout）触发</strong></td><td>其他错误不重试</td></tr></tbody></table><h2 id="统一请求头" tabindex="-1">统一请求头 <a class="header-anchor" href="#统一请求头" aria-label="Permalink to &quot;统一请求头&quot;">​</a></h2><p><strong>基础头</strong>（始终携带）：<code>Content-Type: application/json;charset=UTF-8</code>、<code>Accept-Language</code>、<code>.AspNetCore.Culture</code>、<code>timeZone</code>（localStorage <code>timezone</code>，缺省浏览器时区）。</p><p><strong>登录态头</strong>（<code>handleAuthHeaders</code>，有 token 才注入）：<code>Authorization</code>（getToken）、<code>accountId</code>、<code>tenantId</code>、<code>Token-Type</code>、<code>lang</code>（zh-CN→<code>zh</code> 否则 <code>en</code>）、<code>tenantLang</code>（租户语言，缺省 <code>zh</code>）。</p><h2 id="特殊-baseurl-分流-request-types-六种" tabindex="-1">特殊 baseURL 分流（REQUEST_TYPES 六种） <a class="header-anchor" href="#特殊-baseurl-分流-request-types-六种" aria-label="Permalink to &quot;特殊 baseURL 分流（REQUEST_TYPES 六种）&quot;">​</a></h2><p>配置 <code>requestType</code> 的请求改走对应基址：<code>geometry</code>（几何）/ <code>screen</code>（大屏，取 BASE_API 去掉 <code>/api</code>）/ <code>ezvideo</code>（萤石）/ <code>lecheng</code>（乐橙）/ <code>tplink</code> / <code>yunzhu</code>（云筑）。<code>geometry</code> 与 <code>yunzhu</code> 跳过时间转换。</p><h2 id="自动处理行为" tabindex="-1">自动处理行为 <a class="header-anchor" href="#自动处理行为" aria-label="Permalink to &quot;自动处理行为&quot;">​</a></h2><ol><li><strong>时间转时间戳</strong>：params / body 中的日期字符串（<code>YYYY-MM-DD</code>、<code>YYYY-MM-DD HH:mm[:ss]</code>，dayjs 严格校验）自动 <code>.valueOf()</code> 转时间戳；<code>multipart/form-data</code> 跳过；</li><li><strong>大数安全</strong>：响应经 json-bigint 解析（<code>storeAsString: true</code>）+ 递归 BigInt→string，避免长 ID 精度丢失；</li><li><strong>重复请求去重</strong>：去重键 = <code>MD5([method, url, qs(params), qs(data)].join(&#39;&amp;&#39;))</code>（crypto-js）——<strong>MD5 只用于去重键，不是签名</strong>；支持 <code>cancelRepeat: &#39;before&#39; | &#39;after&#39;</code> 与全局 <code>cancelAllRequests()</code>（AbortController）；</li><li><strong>业务前缀改写</strong>：<code>needsPrefix(VITE_BUILD_VIEWS, url)</code> 按 <code>./prefix-rules</code> 给命中的请求路径加业务前缀（多业务共用一套接口时的路由隔离）。</li></ol><h2 id="_401-302-处理" tabindex="-1">401 / 302 处理 <a class="header-anchor" href="#_401-302-处理" aria-label="Permalink to &quot;401 / 302 处理&quot;">​</a></h2><p>与基座不同，<strong>标品无弹窗、直接整页跳转</strong>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HTTP 401 / 302</span></span>
<span class="line"><span>  ├─ tokenType === &#39;SHARE&#39;（分享页）</span></span>
<span class="line"><span>  │    └─ 清 permission-store 后 reject，不跳转（降级）</span></span>
<span class="line"><span>  └─ 其他</span></span>
<span class="line"><span>       └─ 清 permission-store / tenantList / user-store + sStorage.clear()</span></span>
<span class="line"><span>          → window.location.href = \`\${addressUrl}/#/login?fromSite=\${origin}\`</span></span>
<span class="line"><span>          （location 模式且 VITE_APP_USE_SSO=true 时 addressUrl = VITE_APP_SSO_URL）</span></span></code></pre></div><p>其余错误：<code>Message.error(msg)</code> 并 reject，业务侧 catch 处理。</p>`,15)])])}const g=t(d,[["render",c]]);export{u as __pageData,g as default};
